/** Installed officer creation/portrait/lifecycle with explicit API fixtures. No desktop or saved games. */
import java.lang.reflect.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.awt.Color;import org.json.*;
import com.fs.starfarer.api.*;import com.fs.starfarer.api.campaign.*;import com.fs.starfarer.api.characters.*;import com.fs.starfarer.api.impl.campaign.*;import com.fs.starfarer.api.impl.campaign.events.*;import com.fs.starfarer.api.impl.campaign.intel.*;import com.fs.starfarer.api.util.*;import com.fs.starfarer.campaign.rules.Memory;
public class NativeOfficerPromotionInputs {
 @SuppressWarnings("unchecked") static <T>T proxy(Class<T> t,InvocationHandler h){return (T)Proxy.newProxyInstance(t.getClassLoader(),new Class[]{t},h);}
 static Random mathRandom()throws Exception{Field f=Class.forName("java.lang.Math$RandomNumberGeneratorHolder").getDeclaredField("randomNumberGenerator");f.setAccessible(true);return (Random)f.get(null);}
 static Object field(Object o,String k,Object value,boolean set)throws Exception{for(Class<?> c=o.getClass();c!=null;c=c.getSuperclass())try{Field f=c.getDeclaredField(k);f.setAccessible(true);if(set)f.set(o,value);return f.get(o);}catch(NoSuchFieldException e){}throw new NoSuchFieldException(k);}
 static JSONArray strings(Collection<String> a){return new JSONArray(a);}
 static WeightedRandomPicker<String> picker(JSONObject p)throws Exception{WeightedRandomPicker<String> out=new WeightedRandomPicker<>();JSONArray items=p.getJSONArray("items"),w=p.getJSONArray("weights");for(int i=0;i<items.length();i++)out.add(items.getString(i),(float)w.getDouble(i));return out;}
 static JSONObject data(WeightedRandomPicker<String> p)throws Exception{JSONArray weights=new JSONArray();for(int i=0;i<p.getItems().size();i++)weights.put(p.getWeight(i));return new JSONObject().put("items",strings(p.getItems())).put("weights",weights).put("total",p.getTotal()).put("random",JSONObject.NULL);}
 static class PersonFixture {
  Map<String,Float> skills=new LinkedHashMap<>();Memory memory=new Memory();String portrait="fixture-player",name="Test Officer",rank=null,post=null,personality=null;boolean skip=false;int refreshes=0;FactionAPI faction;PersonAPI person;MutableCharacterStatsAPI stats;
  PersonFixture(){stats=proxy(MutableCharacterStatsAPI.class,(p,m,a)->{switch(m.getName()){case "getLevel":return 1;case "getXP":return 0L;case "getSkillLevel":return skills.getOrDefault((String)a[0],0f);case "increaseSkill":skills.put((String)a[0],skills.getOrDefault((String)a[0],0f)+1);return null;case "setSkipRefresh":skip=(boolean)a[0];return null;case "refreshCharacterStatsEffects":refreshes++;return null;}throw new UnsupportedOperationException("Stats."+m.getName());});person=proxy(PersonAPI.class,(p,m,a)->{switch(m.getName()){case "getStats":return stats;case "getMemoryWithoutUpdate":return memory;case "setFleet":if(a[0]!=null)throw new IllegalArgumentException("expected null fleet");return null;case "getFleet":case "getFleetCommanderStats":return null;case "setRankId":rank=(String)a[0];return null;case "setPostId":post=(String)a[0];return null;case "setPersonality":personality=(String)a[0];return null;case "getPortraitSprite":return portrait;case "getNameString":return name;case "isFemale":return false;case "getFaction":return faction;case "getGender":return FullName.Gender.MALE;}throw new UnsupportedOperationException("Person."+m.getName());});}
 }
 public static void main(String[] args)throws Exception{
  JSONObject input=new JSONObject(new String(System.in.readAllBytes(),StandardCharsets.UTF_8)),settings=input.getJSONObject("settings");Map<String,SkillSpecAPI> specs=new LinkedHashMap<>();JSONArray skillRows=input.getJSONArray("skills");
  for(int i=0;i<skillRows.length();i++){JSONObject s=skillRows.getJSONObject(i);Set<String> tags=new HashSet<>();for(int j=0;j<s.getJSONArray("tags").length();j++)tags.add(s.getJSONArray("tags").getString(j));specs.put(s.getString("id"),proxy(SkillSpecAPI.class,(p,m,a)->{switch(m.getName()){case "getId":return s.getString("id");case "getGoverningAptitudeId":return s.getString("aptitude");case "getTier":return s.getInt("tier");case "getOrder":return (float)s.getDouble("order");case "getReqPoints":return s.getInt("reqPoints");case "isAptitudeEffect":return s.getBoolean("aptitudeEffect");case "isCombatOfficerSkill":return s.getBoolean("combatOfficer");case "hasTag":return tags.contains(a[0]);case "equals":return p==a[0];case "hashCode":return System.identityHashCode(p);}throw new UnsupportedOperationException("Skill."+m.getName());}));}
  Global.setSettings(proxy(SettingsAPI.class,(p,m,a)->{switch(m.getName()){case "getSkillIds":return new ArrayList<>(specs.keySet());case "getSkillSpec":return specs.get(a[0]);case "getPlugin":if(a[0].equals("officerLevelUp"))return new OfficerLevelupPluginImpl();break;case "getFloat":return (float)settings.getDouble((String)a[0]);case "getInt":return settings.getInt((String)a[0]);case "getBoolean":return settings.getBoolean((String)a[0]);case "getColor":{JSONArray c=settings.getJSONArray((String)a[0]);return new Color(c.getInt(0),c.getInt(1),c.getInt(2),c.length()>3?c.getInt(3):255);}}throw new UnsupportedOperationException("Settings."+m.getName());}));
  OfficerLevelupPluginImpl plugin=new OfficerLevelupPluginImpl();
  JSONObject captain=new JSONObject(),raw=input.getJSONObject("factions");for(String id:JSONObject.getNames(raw)){JSONObject traits=raw.getJSONObject(id).optJSONObject("traits"),weights=traits==null?null:traits.optJSONObject("captain");WeightedRandomPicker<String> p=new WeightedRandomPicker<>();if(weights!=null&&JSONObject.getNames(weights)!=null)for(String k:JSONObject.getNames(weights))p.add(k,weights.getInt(k));captain.put(id,data(p));}
  JSONArray results=new JSONArray(),cases=input.getJSONArray("cases");for(int i=0;i<cases.length();i++){
   JSONObject c=cases.getJSONObject(i);PersonFixture person=new PersonFixture();List<String> fixed=new ArrayList<>();JSONArray fix=c.getJSONArray("fixed");for(int j=0;j<fix.length();j++)fixed.add(fix.getString(j));FactionDoctrineAPI doctrine=proxy(FactionDoctrineAPI.class,(p,m,a)->{switch(m.getName()){case "getOfficerSkills":return fixed;case "getOfficerSkillsShuffleProbability":return (float)c.getDouble("shuffle");case "getAggression":return c.getInt("aggression");}throw new UnsupportedOperationException("Doctrine."+m.getName());});
   FactionAPI faction=proxy(FactionAPI.class,(p,m,a)->{switch(m.getName()){case "createRandomPerson":return person.person;case "getDoctrine":return doctrine;case "getId":return "player";case "getPersonalityPicker":return c.has("personality")?picker(c.getJSONObject("personality")):new FactionPersonalityPickerPluginImpl().createPersonalityPicker(person.faction);}throw new UnsupportedOperationException("Faction."+m.getName());});person.faction=faction;
   List<String> picks=new ArrayList<>();int[] dataCalls={0};Global.setFactory(proxy(FactoryAPI.class,(p,m,a)->{if(m.getName().equals("createOfficerData")){if(a[0]!=person.person)throw new IllegalArgumentException();return proxy(OfficerDataAPI.class,(op,om,oa)->{switch(om.getName()){case "addXP":if(!oa[0].equals(0L)||!oa[2].equals(false))throw new IllegalArgumentException("level-one XP arguments");dataCalls[0]++;return null;case "makeSkillPicks":picks.clear();picks.addAll(plugin.pickLevelupSkills(person.person,(Random)oa[0]));dataCalls[0]++;return null;case "canLevelUp":return plugin.getXPForLevel(2)<=0&&2<=plugin.getMaxLevel(person.person);case "getSkillPicks":return picks;case "getPerson":return person.person;}throw new UnsupportedOperationException("OfficerData."+om.getName());});}throw new UnsupportedOperationException("Factory."+m.getName());}));
   Random rng=new Random(Long.parseLong(c.getString("seed")));mathRandom().setSeed(Long.parseLong(c.getString("mathSeed")));PersonAPI created=OfficerManagerEvent.createOfficer(faction,1,OfficerManagerEvent.SkillPickPreference.ANY,true,null,false,false,-1,rng);if(created!=person.person)throw new IllegalArgumentException();results.put(new JSONObject().put("skills",new JSONObject(person.skills)).put("unusedPicks",strings(picks)).put("personality",person.personality).put("rank",person.rank).put("post",person.post).put("refreshes",person.refreshes).put("skipRefresh",person.skip).put("dataCalls",dataCalls[0]).put("nextFloat",rng.nextFloat()).put("nextMathDouble",mathRandom().nextDouble()));
  }
  PersonFixture player=new PersonFixture();int[] crew={0};long[] now={86400000L};CampaignClockAPI clock=proxy(CampaignClockAPI.class,(p,m,a)->{switch(m.getName()){case "getTimestamp":return now[0];case "getElapsedDaysSince":return (float)((now[0]-(Long)a[0])/86400000d);}throw new UnsupportedOperationException("Clock."+m.getName());});CargoAPI cargo=proxy(CargoAPI.class,(p,m,a)->{if(m.getName().equals("getCrew"))return crew[0];throw new UnsupportedOperationException(m.getName());});
  List<OfficerDataAPI> officers=new ArrayList<>();List<AdminData> admins=new ArrayList<>();FleetDataAPI fleetData=proxy(FleetDataAPI.class,(p,m,a)->{if(m.getName().equals("getOfficersCopy"))return officers;throw new UnsupportedOperationException(m.getName());});CampaignFleetAPI fleet=proxy(CampaignFleetAPI.class,(p,m,a)->{switch(m.getName()){case "getCargo":return cargo;case "getFleetData":return fleetData;}throw new UnsupportedOperationException(m.getName());});CharacterDataAPI chars=proxy(CharacterDataAPI.class,(p,m,a)->{if(m.getName().equals("getAdmins"))return admins;throw new UnsupportedOperationException(m.getName());});
  Global.setSector(proxy(SectorAPI.class,(p,m,a)->{switch(m.getName()){case "getClock":return clock;case "getPlayerFleet":return fleet;case "getPlayerPerson":return player.person;case "getCharacterData":return chars;}throw new UnsupportedOperationException("Sector."+m.getName());}));
  PromoteOfficerIntel intel=new PromoteOfficerIntel(null);JSONObject life=new JSONObject().put("noCrewEnded",intel.isEnded()).put("noCrewImportant",intel.isImportant()).put("noCrewPerson",field(intel,"person",null,false)==null).put("name",intel.getName()).put("duration",PromoteOfficerIntel.DURATION);field(intel,"person",player.person,true);life.put("description",intel.getDescText());field(intel,"ended",null,true);field(intel,"ending",null,true);crew[0]=1;intel.setPlayerVisibleTimestamp(now[0]);now[0]+=179*86400000L;life.put("beforeExpiry",intel.shouldRemoveIntel());intel.setImportant(true);now[0]+=86400000L;life.put("atExpiry",intel.shouldRemoveIntel());
  JSONArray portraits=new JSONArray(),pc=input.getJSONArray("portraitCases");for(int i=0;i<pc.length();i++){JSONObject c=pc.getJSONObject(i);officers.clear();admins.clear();player.portrait=c.getString("player");for(int j=0;j<c.getJSONArray("officers").length();j++){PersonFixture pf=new PersonFixture();pf.portrait=c.getJSONArray("officers").getString(j);officers.add(proxy(OfficerDataAPI.class,(p,m,a)->{if(m.getName().equals("getPerson"))return pf.person;throw new UnsupportedOperationException(m.getName());}));}for(int j=0;j<c.getJSONArray("admins").length();j++){PersonFixture pf=new PersonFixture();pf.portrait=c.getJSONArray("admins").getString(j);admins.add(new AdminData(pf.person));}WeightedRandomPicker<String> all=picker(c.getJSONObject("picker"));FactionAPI faction=proxy(FactionAPI.class,(p,m,a)->{if(m.getName().equals("getPortraits"))return all;throw new UnsupportedOperationException(m.getName());});mathRandom().setSeed(Long.parseLong(c.getString("seed")));String picked=OfficerManagerEvent.pickPortraitPreferNonDuplicate(faction,FullName.Gender.MALE);portraits.put(new JSONObject().put("portrait",picked==null?JSONObject.NULL:picked).put("nextMathDouble",mathRandom().nextDouble()));}
  System.out.print("@@OFFICER_PROMOTION@@"+new JSONObject().put("captainPersonalities",captain).put("results",results).put("lifecycle",life).put("portraits",portraits));
 }
}
